export const HOME_SEED_IDS = {
  tasks: tasks.map((t) => t.id),
  events: events.map((e) => e.id),
  news: news.map((n) => n.id),
  updates: updates.map((u) => u.id),
  replies: replies.map((r) => r.id),
} as const;

/** home module seed. Populate the module's collections with stable ids (idempotent). */
export function seedHome(db: Database) {
  db.tasks.putMany(tasks);
  db.events.putMany(events);
  db.news.putMany(news);
  db.updates.putMany(updates);
  db.collection<UpdateReply>(HOME_COLLECTIONS.replies).putMany(replies);
}
